"""Filter and aggregate RFC-4180-style CSV files."""

from __future__ import annotations

import argparse
import csv
import json
import sys
from decimal import Decimal, InvalidOperation, localcontext
from pathlib import Path
from typing import Sequence, TextIO


class CsvInsightsError(Exception):
    """An input or usage error that should be shown without a traceback."""


def parse_arguments(argv: Sequence[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Filter CSV rows and optionally calculate grouped sums/averages."
    )
    parser.add_argument("input", metavar="INPUT.csv", type=Path)
    parser.add_argument(
        "--where",
        action="append",
        default=[],
        metavar="COLUMN=VALUE",
        help="keep rows whose column exactly equals value (repeatable)",
    )
    parser.add_argument("--group-by", metavar="COLUMN")
    parser.add_argument("--sum", dest="sum_column", metavar="COLUMN")
    parser.add_argument("--avg", dest="avg_column", metavar="COLUMN")
    parser.add_argument("--output", choices=("json", "csv"), default="json")
    args = parser.parse_args(argv)

    if (args.sum_column or args.avg_column) and not args.group_by:
        parser.error("--sum and --avg require --group-by")
    if args.group_by and not (args.sum_column or args.avg_column):
        parser.error("--group-by requires --sum and/or --avg")
    return args


def parse_filters(raw_filters: Sequence[str]) -> list[tuple[str, str]]:
    filters: list[tuple[str, str]] = []
    for raw_filter in raw_filters:
        column, separator, value = raw_filter.partition("=")
        if not separator or not column:
            raise CsvInsightsError(
                f"malformed filter {raw_filter!r}; expected COLUMN=VALUE"
            )
        filters.append((column, value))
    return filters


def read_csv(path: Path) -> tuple[list[str], list[tuple[int, dict[str, str]]]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as source:
            reader = csv.reader(source, strict=True)
            try:
                header = next(reader)
            except StopIteration:
                raise CsvInsightsError("input CSV is empty") from None

            if not header or any(name == "" for name in header):
                raise CsvInsightsError("CSV headers must be non-empty")
            duplicates = sorted({name for name in header if header.count(name) > 1})
            if duplicates:
                raise CsvInsightsError(
                    "CSV headers must be unique; duplicate: "
                    + ", ".join(repr(name) for name in duplicates)
                )

            rows: list[tuple[int, dict[str, str]]] = []
            for record_number, fields in enumerate(reader, start=2):
                if len(fields) != len(header):
                    raise CsvInsightsError(
                        f"row {record_number} has {len(fields)} fields; "
                        f"expected {len(header)}"
                    )
                rows.append((record_number, dict(zip(header, fields))))
            return header, rows
    except CsvInsightsError:
        raise
    except (OSError, UnicodeError, csv.Error) as error:
        raise CsvInsightsError(f"cannot read {path}: {error}") from error


def require_columns(header: Sequence[str], columns: Sequence[str | None]) -> None:
    known = set(header)
    for column in columns:
        if column is not None and column not in known:
            raise CsvInsightsError(f"unknown column: {column!r}")


def decimal_cell(value: str, row_number: int, column: str) -> Decimal:
    if value == "":
        raise CsvInsightsError(f"row {row_number}, column {column!r}: blank numeric value")
    try:
        number = Decimal(value)
    except InvalidOperation:
        raise CsvInsightsError(
            f"row {row_number}, column {column!r}: invalid numeric value {value!r}"
        ) from None
    if not number.is_finite():
        raise CsvInsightsError(
            f"row {row_number}, column {column!r}: invalid numeric value {value!r}"
        )
    return number


def decimal_string(number: Decimal) -> str:
    """Return fixed-point Decimal text without insignificant trailing zeroes."""
    text = format(number, "f")
    if "." in text:
        text = text.rstrip("0").rstrip(".")
    if text in ("", "-0"):
        return "0"
    return text


def aggregate(
    rows: Sequence[tuple[int, dict[str, str]]],
    group_column: str,
    sum_column: str | None,
    avg_column: str | None,
) -> tuple[list[str], list[dict[str, str]]]:
    numeric_columns = list(dict.fromkeys(c for c in (sum_column, avg_column) if c))
    groups: dict[str, dict[str, list[Decimal]]] = {}

    for row_number, row in rows:
        values = {
            column: decimal_cell(row[column], row_number, column)
            for column in numeric_columns
        }
        bucket = groups.setdefault(
            row[group_column], {column: [] for column in numeric_columns}
        )
        for column, value in values.items():
            bucket[column].append(value)

    output_header = [group_column]
    if sum_column:
        output_header.append(f"sum_{sum_column}")
    if avg_column:
        output_header.append(f"avg_{avg_column}")

    output_rows: list[dict[str, str]] = []
    for group_value in sorted(groups):
        result = {group_column: group_value}
        bucket = groups[group_value]
        if sum_column:
            result[f"sum_{sum_column}"] = decimal_string(sum(bucket[sum_column], Decimal(0)))
        if avg_column:
            values = bucket[avg_column]
            # Extra precision avoids losing significant digits for typical input while
            # retaining Decimal's deterministic rounding for repeating averages.
            precision = max(28, sum(len(value.as_tuple().digits) for value in values) + 10)
            with localcontext() as context:
                context.prec = precision
                average = sum(values, Decimal(0)) / Decimal(len(values))
            result[f"avg_{avg_column}"] = decimal_string(average)
        output_rows.append(result)
    return output_header, output_rows


def emit_json(rows: Sequence[dict[str, str]], output: TextIO) -> None:
    json.dump(rows, output, ensure_ascii=False, separators=(",", ":"))
    output.write("\n")


def emit_csv(
    header: Sequence[str], rows: Sequence[dict[str, str]], output: TextIO
) -> None:
    writer = csv.DictWriter(output, fieldnames=header, lineterminator="\r\n")
    writer.writeheader()
    writer.writerows(rows)


def run(argv: Sequence[str] | None = None, output: TextIO = sys.stdout) -> None:
    args = parse_arguments(argv)
    filters = parse_filters(args.where)
    header, numbered_rows = read_csv(args.input)
    require_columns(
        header,
        [*(column for column, _ in filters), args.group_by, args.sum_column, args.avg_column],
    )

    filtered = [
        (row_number, row)
        for row_number, row in numbered_rows
        if all(row[column] == value for column, value in filters)
    ]

    if args.group_by:
        output_header, rows = aggregate(
            filtered, args.group_by, args.sum_column, args.avg_column
        )
    else:
        output_header = header
        rows = [row for _, row in filtered]

    if args.output == "json":
        emit_json(rows, output)
    else:
        emit_csv(output_header, rows, output)


def main() -> int:
    try:
        run()
    except CsvInsightsError as error:
        print(f"error: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
import csv
import json
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path


PROJECT = Path(__file__).parent
PROGRAM = PROJECT / "main.py"


class CsvInsightsTests(unittest.TestCase):
    def invoke(self, contents, *arguments):
        with tempfile.TemporaryDirectory() as directory:
            input_path = Path(directory) / "input.csv"
            input_path.write_text(contents, encoding="utf-8", newline="")
            before = input_path.read_bytes()
            result = subprocess.run(
                [sys.executable, str(PROGRAM), str(input_path), *arguments],
                text=True,
                capture_output=True,
                check=False,
            )
            self.assertEqual(before, input_path.read_bytes(), "input file was modified")
            return result

    def test_json_filter_preserves_rows_and_parses_quoted_fields(self):
        result = self.invoke(
            'name,note,team\r\n"Ada","first, second","A"\r\n'
            '"Bob","line one\nline two","B"\r\n'
            '"Amy","ok","A"\r\n',
            "--where", "team=A",
        )
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(
            json.loads(result.stdout),
            [
                {"name": "Ada", "note": "first, second", "team": "A"},
                {"name": "Amy", "note": "ok", "team": "A"},
            ],
        )

    def test_filters_combine_with_and_and_allow_equals_in_value(self):
        result = self.invoke(
            "a,b\r\nx,1=2\r\nx,2\r\ny,1=2\r\n",
            "--where", "a=x", "--where", "b=1=2",
        )
        self.assertEqual(json.loads(result.stdout), [{"a": "x", "b": "1=2"}])

    def test_grouped_sum_and_average_are_sorted_and_minimal(self):
        result = self.invoke(
            "group,amount,count\r\nz,1.20,2\r\na,0.01,1\r\n"
            "z,1.30,3\r\na,0.02,2\r\n",
            "--group-by", "group", "--sum", "amount", "--avg", "count",
        )
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(
            json.loads(result.stdout),
            [
                {"group": "a", "sum_amount": "0.03", "avg_count": "1.5"},
                {"group": "z", "sum_amount": "2.5", "avg_count": "2.5"},
            ],
        )

    def test_csv_output_has_header_and_rfc_quoting(self):
        result = self.invoke('name,note\r\nAda,"hello, world"\r\n', "--output", "csv")
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(
            list(csv.reader(result.stdout.splitlines())),
            [["name", "note"], ["Ada", "hello, world"]],
        )
        self.assertIn('"hello, world"', result.stdout)

    def test_rejects_invalid_headers_and_row_lengths(self):
        for contents, message in (
            ("a,a\r\n1,2\r\n", "headers must be unique"),
            ("a,\r\n1,2\r\n", "headers must be non-empty"),
            ("a,b\r\n1\r\n", "row 2 has 1 fields"),
        ):
            with self.subTest(contents=contents):
                result = self.invoke(contents)
                self.assertNotEqual(result.returncode, 0)
                self.assertIn(message, result.stderr)

    def test_rejects_unknown_columns_and_bad_filters(self):
        unknown = self.invoke("a\r\nx\r\n", "--where", "missing=x")
        malformed = self.invoke("a\r\nx\r\n", "--where", "broken")
        self.assertNotEqual(unknown.returncode, 0)
        self.assertIn("unknown column", unknown.stderr)
        self.assertNotEqual(malformed.returncode, 0)
        self.assertIn("malformed filter", malformed.stderr)

    def test_numeric_errors_identify_row_and_column(self):
        for value, phrase in (("", "blank numeric"), ("wat", "invalid numeric"), ("NaN", "invalid numeric")):
            with self.subTest(value=value):
                result = self.invoke(
                    f"group,value\r\na,{value}\r\n",
                    "--group-by", "group", "--sum", "value",
                )
                self.assertNotEqual(result.returncode, 0)
                self.assertIn("row 2, column 'value'", result.stderr)
                self.assertIn(phrase, result.stderr)

    def test_aggregation_requires_group_by(self):
        result = self.invoke("a,b\r\nx,1\r\n", "--sum", "b")
        self.assertNotEqual(result.returncode, 0)
        self.assertIn("require --group-by", result.stderr)


if __name__ == "__main__":
    unittest.main()
# CSV Insights

A dependency-free Python 3.11+ command-line tool for filtering and grouped
aggregation of RFC-compatible CSV files.

```sh
python3 main.py INPUT.csv [--where COLUMN=VALUE ...] \
  [--group-by COLUMN] [--sum COLUMN] [--avg COLUMN] [--output json|csv]
```

JSON is the default output. Filters are exact string comparisons and repeated
filters are combined with AND. `--sum` and `--avg` require `--group-by`; both
may be used together. Numeric calculations use `decimal.Decimal`.

Examples:

```sh
python3 main.py sales.csv --where region=East
python3 main.py sales.csv --group-by region --sum revenue --avg units --output csv
```

Errors (invalid CSV structure, unknown columns, malformed filters, and invalid
numeric cells) are written to stderr and return a non-zero exit status. The
input file is only opened for reading.

Run the self-tests with:

```sh
python3 -m unittest -v
```

